svg.script:
(function(){
  var root = document.querySelector('.a6p6-root');
  if(!root){
    var scripts = document.getElementsByTagName('script');
    var s = scripts[scripts.length-1];
    root = s && s.ownerSVGElement ? s.ownerSVGElement : null;
  }
  if(!root) return;

  function Q(sel){ return root.querySelector(sel); }
  var tip = Q('#a6p6-tip');
  var statusEl = Q('#a6p6-status');
  var liveEl = Q('#a6p6-live');
  var resetBtn = Q('#a6p6-btn-reset');
  var reduce = false;
  try {
    reduce = window.matchMedia && window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  } catch(e){ reduce = false; }

  var labels = {
    deprime: {
      tip1: 'Deprime ↓',
      tip2: 'AED e benzo baixam o funcionamento neuronal',
      stroke: 'var(--a6p6-teal, #2DD4BF)',
      status: 'Deprime · seta para baixo',
      live: 'Depressores do SNC: tontura, sonolência, cognição mais lenta — lógica, não bula.'
    },
    dispara: {
      tip1: 'Dispara ↑',
      tip2: 'Psicoestimulantes empurram o excesso',
      stroke: 'var(--a6p6-coral, #F87171)',
      status: 'Dispara · seta para cima',
      live: 'Cocaína e anfetamina podem causar crise na intoxicação — empurram o limiar.'
    },
    aed: {
      tip1: 'AED',
      tip2: 'Diminui funcionamento neuronal · inicia e retira devagar',
      stroke: 'var(--a6p6-teal, #2DD4BF)',
      status: 'AED · depressor crônico',
      live: 'Titulação: sobe devagar, retira devagar. Dose no teto sem titulação → sedação excessiva.'
    },
    benzo: {
      tip1: 'Benzodiazepínico',
      tip2: 'Inibe o neurônio em crise em curso',
      stroke: 'var(--a6p6-indigo, #818CF8)',
      status: 'Benzo · freio de emergência',
      live: 'Na crise em curso, o benzo deprime o neurônio hiperexcitado — freio agudo.'
    },
    coca: {
      tip1: 'Cocaína',
      tip2: 'Pode causar crise na intoxicação',
      stroke: 'var(--a6p6-coral, #F87171)',
      status: 'Cocaína · intoxicação',
      live: 'Estimulante: o excesso sobe. Crise é padrão possível da intoxicação, não da retirada.'
    },
    anf: {
      tip1: 'Anfetamina',
      tip2: 'Pode causar crise na intoxicação',
      stroke: 'var(--a6p6-coral, #F87171)',
      status: 'Anfetamina · intoxicação',
      live: 'Mesma seta da cocaína: intoxicação empurra o excesso e pode disparar crise.'
    },
    alcool: {
      tip1: 'Álcool · tempo',
      tip2: 'Intoxicação ≠ crise · abstinência gera crise',
      stroke: 'var(--a6p6-gold, #FBBF24)',
      status: 'Álcool · pegadinha do tempo',
      live: 'Não confunda: o padrão de crise do álcool é a abstinência, não a intoxicação.'
    },
    adesao: {
      tip1: 'Adesão',
      tip2: 'Parou o remédio → a crise volta',
      stroke: 'var(--a6p6-gold, #FBBF24)',
      status: 'Adesão · motivo conceitual de recorrência',
      live: 'Em controlado, o principal motivo conceitual de voltar a ter crise é não tomar o AED.'
    }
  };

  function setMode(mode){
    if(!mode){
      root.removeAttribute('data-mode');
      root.setAttribute('data-playing','0');
      return;
    }
    root.setAttribute('data-mode', mode);
    if(!reduce && (mode === 'deprime' || mode === 'dispara')){
      root.setAttribute('data-playing','1');
    } else {
      root.setAttribute('data-playing','0');
    }
  }

  function clientToSvg(cx, cy){
    var pt = root.createSVGPoint();
    pt.x = cx; pt.y = cy;
    var m = root.getScreenCTM();
    if(!m) return {x:cx, y:cy};
    var p = pt.matrixTransform(m.inverse());
    return {x:p.x, y:p.y};
  }

  function showTip(cx, cy, t1, t2, stroke){
    if(!tip) return;
    var t1el = Q('#a6p6-tip-t1');
    var t2el = Q('#a6p6-tip-t2');
    var bg = Q('#a6p6-tip-bg');
    if(t1el) t1el.textContent = t1;
    if(t2el) t2el.textContent = t2;
    if(bg) bg.setAttribute('stroke', stroke || 'var(--a6p6-gold, #FBBF24)');
    var p = clientToSvg(cx, cy);
    var w = 300, h = 58, off = 14;
    var x = p.x + off;
    var y = p.y + off;
    if(x + w > 820) x = p.x - w - off;
    if(y + h > 660) y = p.y - h - off;
    if(x < 8) x = 8;
    if(y < 8) y = 8;
    tip.setAttribute('transform', 'translate(' + x + ',' + y + ')');
    tip.setAttribute('opacity', '1');
  }

  function hideTip(){
    if(tip) tip.setAttribute('opacity', '0');
  }

  function applyLabel(key, cx, cy){
    var L = labels[key];
    if(!L) return;
    var mode = key;
    if(key === 'aed' || key === 'benzo') mode = 'deprime';
    if(key === 'coca' || key === 'anf') mode = 'dispara';
    setMode(mode);
    if(cx != null && cy != null) showTip(cx, cy, L.tip1, L.tip2, L.stroke);
    if(statusEl){
      statusEl.textContent = L.status;
      statusEl.setAttribute('fill', L.stroke);
    }
    if(liveEl) liveEl.textContent = L.live;
  }

  function bindHotspot(el, key){
    if(!el) return;
    var L = labels[key];
    function activate(ev){
      if(ev && ev.stopPropagation) ev.stopPropagation();
      var cx = (ev && ev.clientX != null) ? ev.clientX : el.getBoundingClientRect().left + 40;
      var cy = (ev && ev.clientY != null) ? ev.clientY : el.getBoundingClientRect().top + 20;
      applyLabel(key, cx, cy);
    }
    el.addEventListener('mouseenter', function(ev){
      if(ev && ev.stopPropagation) ev.stopPropagation();
      applyLabel(key, ev.clientX, ev.clientY);
    });
    el.addEventListener('mousemove', function(ev){
      if(ev && ev.stopPropagation) ev.stopPropagation();
      if(tip && tip.getAttribute('opacity') === '1' && L){
        showTip(ev.clientX, ev.clientY, L.tip1, L.tip2, L.stroke);
      }
    });
    el.addEventListener('mouseleave', function(ev){
      if(ev && ev.stopPropagation) ev.stopPropagation();
      hideTip();
    });
    el.addEventListener('click', activate);
    el.addEventListener('focus', function(){
      var b = el.getBoundingClientRect();
      applyLabel(key, b.left + b.width/2, b.top + b.height/2);
    });
    el.addEventListener('blur', function(){ hideTip(); });
    el.addEventListener('keydown', function(ev){
      if(ev.key === 'Enter' || ev.key === ' ' || ev.key === 'Spacebar'){
        ev.preventDefault();
        activate(ev);
      }
    });
  }

  function bindChip(el, key){
    if(!el) return;
    var L = labels[key];
    function go(ev){
      var cx = (ev && ev.clientX != null) ? ev.clientX : el.getBoundingClientRect().left + 40;
      var cy = (ev && ev.clientY != null) ? ev.clientY : el.getBoundingClientRect().top + 14;
      applyLabel(key, cx, cy);
    }
    el.addEventListener('mouseenter', function(ev){
      applyLabel(key, ev.clientX, ev.clientY);
    });
    el.addEventListener('mousemove', function(ev){
      if(tip && tip.getAttribute('opacity') === '1' && L){
        showTip(ev.clientX, ev.clientY, L.tip1, L.tip2, L.stroke);
      }
    });
    el.addEventListener('mouseleave', function(){ hideTip(); });
    el.addEventListener('click', go);
    el.addEventListener('focus', function(){
      var b = el.getBoundingClientRect();
      applyLabel(key, b.left + b.width/2, b.top + b.height/2);
    });
    el.addEventListener('blur', function(){ hideTip(); });
    el.addEventListener('keydown', function(ev){
      if(ev.key === 'Enter' || ev.key === ' ' || ev.key === 'Spacebar'){
        ev.preventDefault();
        go(ev);
      }
    });
  }

  bindHotspot(Q('#a6p6-pan-l'), 'deprime');
  bindHotspot(Q('#a6p6-pan-r'), 'dispara');
  bindHotspot(Q('#a6p6-hs-aed'), 'aed');
  bindHotspot(Q('#a6p6-hs-benzo'), 'benzo');
  bindHotspot(Q('#a6p6-hs-coca'), 'coca');
  bindHotspot(Q('#a6p6-hs-anf'), 'anf');
  bindHotspot(Q('#a6p6-hs-alcool'), 'alcool');
  bindHotspot(Q('#a6p6-hs-adesao'), 'adesao');

  bindChip(Q('#a6p6-chip-deprime'), 'deprime');
  bindChip(Q('#a6p6-chip-dispara'), 'dispara');
  bindChip(Q('#a6p6-chip-alcool'), 'alcool');
  bindChip(Q('#a6p6-chip-adesao'), 'adesao');

  if(resetBtn){
    function doReset(){
      setMode(null);
      hideTip();
      if(statusEl){
        statusEl.textContent = 'Toque um prato · o álcool · ou a adesão';
        statusEl.setAttribute('fill', 'var(--a6p6-muted, #94A3B8)');
      }
      if(liveEl){
        liveEl.textContent = 'A seta do fármaco decide se o neurônio desce ou sobe no limiar.';
      }
    }
    resetBtn.addEventListener('click', doReset);
    resetBtn.addEventListener('keydown', function(ev){
      if(ev.key === 'Enter' || ev.key === ' ' || ev.key === 'Spacebar'){
        ev.preventDefault();
        doReset();
      }
    });
  }

  root.addEventListener('click', function(ev){
    var t = ev.target;
    if(!t) return;
    var keep = false;
    var nodes = root.querySelectorAll('.a6p6-hs, .a6p6-chip, .a6p6-btn');
    for(var i = 0; i < nodes.length; i++){
      if(nodes[i].contains(t) || nodes[i] === t){ keep = true; break; }
    }
    if(!keep) hideTip();
  });

  setMode(null);
})();
